const BASE_USDC = '0x833589fcd6edb6e08f4c7c32d4f71b54bda02913';
const TRANSFER_TOPIC = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef';
const HEX_QTY_RE = /^0x[0-9a-fA-F]+$/;
const TOPIC_WORD_RE = /^0x[0-9a-fA-F]{64}$/;

const SECRET = String($env.WEBHOOK_HMAC_SECRET || '').trim();
if (SECRET.length < 16) {
  throw new Error('WEBHOOK_HMAC_SECRET (>= 16 chars) must be configured');
}
const PAY_TO = String($env.PAY_TO_EVM_ADDRESS || '').trim().toLowerCase();
if (!/^0x[0-9a-f]{40}$/.test(PAY_TO)) {
  throw new Error('PAY_TO_EVM_ADDRESS must be a valid non-empty 0x EVM address');
}
const EXPECTED_RAW = String($env.EXPECTED_AMOUNT_ATOMIC || '').trim();
if (!/^[1-9][0-9]*$/.test(EXPECTED_RAW)) {
  throw new Error('EXPECTED_AMOUNT_ATOMIC must be a positive integer string');
}
const EXPECTED_AMOUNT_ATOMIC = BigInt(EXPECTED_RAW);
const BASE_RPC_URL = String($env.BASE_RPC_URL || '').trim();
if (!/^https?:\/\//i.test(BASE_RPC_URL)) {
  throw new Error('BASE_RPC_URL must be configured');
}
const MIN_CONF_RAW = String($env.MIN_CONFIRMATIONS || '2').trim();
if (!/^[1-9][0-9]*$/.test(MIN_CONF_RAW)) {
  throw new Error('MIN_CONFIRMATIONS must be a positive integer >= 1');
}
const MIN_CONFIRMATIONS = BigInt(MIN_CONF_RAW);
const MAX_AGE_RAW = String($env.MAX_WEBHOOK_AGE_SECONDS || '300').trim();
if (!/^[1-9][0-9]*$/.test(MAX_AGE_RAW)) {
  throw new Error('MAX_WEBHOOK_AGE_SECONDS must be a positive integer');
}
const MAX_WEBHOOK_AGE_SECONDS = Number(MAX_AGE_RAW);

function parseStrictHexBigInt(val, label) {
  if (typeof val !== 'string' || !HEX_QTY_RE.test(val.trim())) {
    throw new Error(`Invalid ${label} hex quantity`);
  }
  return BigInt(val.trim());
}

function extractRawPayload(item) {
  const binData = item?.binary?.data?.data;
  if (typeof binData === 'string' && binData.length > 0) {
    return Buffer.from(binData, 'base64').toString('utf8');
  }
  if (binData instanceof Uint8Array && binData.length > 0) {
    return Buffer.from(binData).toString('utf8');
  }
  if (typeof item?.json?.rawBody === 'string' && item.json.rawBody.length > 0) {
    return item.json.rawBody;
  }
  if (item?.json?.body !== undefined) {
    return JSON.stringify(item.json.body);
  }
  return '';
}

async function verifySignedWebhook(secret, tsHeader, rawPayload, sigHeader) {
  const cleanTs = String(tsHeader || '').trim();
  if (!/^\d{10}$/.test(cleanTs)) {
    throw new Error('Unauthorized: missing or invalid x-webhook-timestamp (Unix seconds required)');
  }
  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - Number(cleanTs)) > MAX_WEBHOOK_AGE_SECONDS) {
    throw new Error('Unauthorized: webhook timestamp outside allowed replay window');
  }
  const cleanSig = String(sigHeader || '').trim().replace(/^sha256=/i, '').toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(cleanSig)) {
    throw new Error('Unauthorized: missing or malformed webhook HMAC signature');
  }
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(`${cleanTs}.${rawPayload}`)));
  let diff = 0;
  for (let i = 0; i < 32; i++) {
    const byte = Number.parseInt(cleanSig.slice(i * 2, i * 2 + 2), 16);
    diff |= mac[i] ^ byte;
  }
  if (diff !== 0) {
    throw new Error('Unauthorized: invalid webhook HMAC signature');
  }
}

async function rpcCall(method, params) {
  const res = await fetch(BASE_RPC_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
    signal: AbortSignal.timeout(10000)
  });
  if (!res.ok) throw new Error(`Base RPC HTTP ${res.status}`);
  const body = await res.json();
  if (body.error) throw new Error(body.error.message || 'Base RPC error');
  return body.result;
}

const staticData = typeof $getWorkflowStaticData === 'function' ? $getWorkflowStaticData('global') : null;
if (staticData && !Array.isArray(staticData.seenReplayKeys)) {
  staticData.seenReplayKeys = [];
}

const inputItems = typeof $input !== 'undefined' ? $input.all() : items;
const verified = [];

for (const item of inputItems) {
  const json = item.json || {};
  const headers = {};
  for (const [k, v] of Object.entries(json.headers || {})) {
    headers[String(k).toLowerCase()] = String(v ?? '');
  }
  const rawPayload = extractRawPayload(item);
  if (!rawPayload) {
    throw new Error('Unauthorized: missing webhook payload body');
  }
  await verifySignedWebhook(
    SECRET,
    headers['x-webhook-timestamp'],
    rawPayload,
    headers['x-webhook-signature'] || headers['x-signature-256']
  );

  const payload = JSON.parse(rawPayload);
  const txHash = String(payload?.txHash || payload?.hash || '').trim().toLowerCase();
  if (!/^0x[0-9a-f]{64}$/.test(txHash)) continue;

  const replayKey = `base:${txHash}`;
  if (staticData && staticData.seenReplayKeys.includes(replayKey)) continue;

  const receipt = await rpcCall('eth_getTransactionReceipt', [txHash]);
  if (!receipt || typeof receipt.status !== 'string' || receipt.status.toLowerCase() !== '0x1') continue;
  const txBlock = parseStrictHexBigInt(receipt.blockNumber, 'receipt.blockNumber');
  const latestHex = await rpcCall('eth_blockNumber', []);
  const latestBlock = parseStrictHexBigInt(latestHex, 'eth_blockNumber');
  if (latestBlock < txBlock) continue;
  const confirmations = latestBlock - txBlock + 1n;
  if (confirmations < MIN_CONFIRMATIONS) continue;

  let totalAtomic = 0n;
  let matchCount = 0;
  const senderSet = new Set();
  for (const log of receipt.logs || []) {
    if (String(log?.address || '').trim().toLowerCase() !== BASE_USDC) continue;
    if (!Array.isArray(log.topics) || log.topics.length < 3) continue;
    if (String(log.topics[0]).toLowerCase() !== TRANSFER_TOPIC) continue;
    if (!TOPIC_WORD_RE.test(String(log.topics[1])) || !TOPIC_WORD_RE.test(String(log.topics[2]))) continue;
    const from = `0x${String(log.topics[1]).slice(-40).toLowerCase()}`;
    const to = `0x${String(log.topics[2]).slice(-40).toLowerCase()}`;
    if (to !== PAY_TO) continue;
    totalAtomic += parseStrictHexBigInt(log.data, 'log.data');
    senderSet.add(from);
    matchCount += 1;
  }

  if (matchCount > 0 && totalAtomic >= EXPECTED_AMOUNT_ATOMIC) {
    if (staticData) {
      staticData.seenReplayKeys.push(replayKey);
      if (staticData.seenReplayKeys.length > 1000) {
        staticData.seenReplayKeys.splice(0, staticData.seenReplayKeys.length - 1000);
      }
    }
    const senders = Array.from(senderSet);
    verified.push({
      json: {
        event: 'base_usdc_confirmed',
        replayKey,
        txHash,
        from: senders.length === 1 ? senders[0] : null,
        senders,
        to: PAY_TO,
        amountAtomic: totalAtomic.toString(),
        confirmations: Number(confirmations),
        blockNumber: Number(txBlock)
      }
    });
  }
}

return verified;
